{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
}
|group#visual| "V1 · Model and instance" { layout: grid; columns: repeat(2); gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "UMF document · metadata" { width: 240; } [
    |cell#detail| "sales.id and sales.status are required\nstring Fields."
  ]
  |box#n2| "Record and ordered Key" { width: 240; } [
    |cell#detail| "sales.order contains both Fields. Its\nprimary Key pk contains sales.id."
  ]
  |box#n3| "Module extension" { width: 240; } [
    |cell#detail| "sales.extensions → umf.actions →\napprove declares the permitted status\nassignment."
  ]
  |box#n4| "Separate business data" { width: 240; } [
    |cell#detail| "An example stored order has id order-1\nand status pending. It is not a row\ninside the UMF document."
  ]
  n2 -> n1 "References the declared Fields" .e1 { along: 0.35; }
]
